import Foundation
import simd
import XCTest
import ShuttlCore
@testable import ShuttlPlayers

/// Port of backend/tests/test_players.py (scenes come from the fixtures, which were
/// generated by that file's own `_scene` / `_person` / `_doubles_frames`).
final class BehaviourTests: XCTestCase {
    private var synthetic: [String: PlayerCase] = [:]

    func scene(_ name: String) throws -> PlayerCase {
        if synthetic.isEmpty {
            for c in Fx.list(try Fx.load("synthetic")) {
                let pc = try PlayerCase(c)
                synthetic[pc.name] = pc
            }
        }
        return try XCTUnwrap(synthetic[name], "missing scene \(name)")
    }

    func assemble(_ pc: PlayerCase, doubles: Bool? = nil) -> PlayerTracks {
        PlayerTracker.assembleTracks(pc.candidates(), meta: pc.meta, camera: pc.camera, doubles: doubles ?? pc.doubles)
    }

    func byTrack(_ obs: [PlayerObservation]) -> [Int: [PlayerObservation]] {
        Dictionary(grouping: obs, by: \.trackID)
    }

    func gt(_ pc: PlayerCase) -> [String: [SIMD2<Double>]] {
        Fx.dict(pc.raw["gt"]).mapValues(Fx.v2)
    }

    /// tests/test_players._check_identity
    func checkIdentity(_ obs: [PlayerObservation], _ gt: [String: [SIMD2<Double>]], _ idOf: [String: Int],
                       tol: Double = 0.35, minCov: Double = 0.9, file: StaticString = #filePath, line: UInt = #line) {
        let tracks = byTrack(obs)
        XCTAssertEqual(Set(tracks.keys), Set(idOf.values), file: file, line: line)
        let n = gt.values.first!.count
        for (name, tid) in idOf {
            guard let o = tracks[tid] else { XCTFail("no track \(tid)", file: file, line: line); continue }
            XCTAssertEqual(Set(o.map(\.frame)).count, o.count, "duplicate frames \(tid)", file: file, line: line)
            XCTAssertGreaterThanOrEqual(Double(o.count), minCov * Double(n), "coverage \(name)", file: file, line: line)
            let err = o.map { simd_length($0.footWorld! - gt[name]![$0.frame]) }
            XCTAssertLessThan(NP.median(err), 0.12, "median err \(name)", file: file, line: line)
            XCTAssertLessThan(NP.percentile(err, 99), tol, "p99 err \(name)", file: file, line: line)
            XCTAssertEqual(Set(o.map(\.side)), [name.hasPrefix("n") ? .near : .far], name, file: file, line: line)
        }
    }

    // MARK: foot point / gating

    func testFootPointPrefersAnklesThenBboxBottom() throws {
        let pc = try scene("net_lunge_side")
        let d = pc.detections[0]
        let box = [d.boxes[0]]
        var kps = KeypointArray([d.keypoints[0]])
        let (foot, ank) = PlayerGeometry.footPixels(boxes: box, kps: kps)
        XCTAssertTrue(ank[0])
        XCTAssertEqual(foot[0].x, (kps.x(0, 15) + kps.x(0, 16)) / 2)
        kps.values[15 * 3 + 2] = 0.1                                   // one ankle occluded
        let (foot2, ank2) = PlayerGeometry.footPixels(boxes: box, kps: kps)
        XCTAssertFalse(ank2[0]); XCTAssertEqual(foot2[0].y, box[0].y2)
        let pos = PlayerGeometry.floorPositions(camera: pc.camera!, footPx: foot, fromAnkle: ank)
        XCTAssertLessThan(simd_length(pos[0] - gt(pc)["near"]![0]), 0.1)   // 3 px keypoint noise
    }

    func testGatingRejectsOfficialsAndSpectators() throws {
        let pc = try scene("singles_240")
        let d = pc.detections[0]
        let off = (d.n - 9)..<d.n                                        // officials are appended last
        let dets = FrameDetections(boxes: Array(d.boxes[off]), scores: [Double](repeating: 0.9, count: 9),
                                   keypoints: Array(d.keypoints[off]))
        let c = Candidates.build(frame: 0, detections: dets, camera: pc.camera, imageSize: pc.meta.size)
        XCTAssertTrue(c.unary.allSatisfy { $0 > PlayersConfig.default.cMiss }, "\(c.unary)")
        // umpire on the raised chair (first official) is never a player
        let ump = FrameDetections(boxes: [d.boxes[off.lowerBound]], scores: [0.95], keypoints: [d.keypoints[off.lowerBound]])
        let cu = Candidates.build(frame: 0, detections: ump, camera: pc.camera, imageSize: pc.meta.size)
        XCTAssertTrue(cu.n == 0 || cu.unary[0] > PlayersConfig.default.cMiss)
    }

    // MARK: identity / sides

    func testSinglesExactlyTwoConsistentIds() throws {
        let pc = try scene("singles_240")
        let tr = assemble(pc)
        XCTAssertFalse(tr.doubles)
        checkIdentity(tr.observations, gt(pc), ["near": 1, "far": 2])
        XCTAssertTrue(tr.observations.allSatisfy { $0.keypoints?.count == 17 })
        XCTAssertTrue(Set(tr.observations.filter { $0.trackID == 1 }.map(\.frame)).isSuperset(of: 10..<230))
    }

    func testDoublesFourIdsLeftRightOrder() throws {
        let pc = try scene("doubles_auto")
        let tr = assemble(pc)
        XCTAssertTrue(tr.doubles)                                         // auto-detected
        checkIdentity(tr.observations, gt(pc), ["n_right": 1, "n_left": 3, "f_right": 2, "f_left": 4])
    }

    func testPlayerNearNetKeepsSide() throws {
        let pc = try scene("net_lunge_side")
        let tr = byTrack(assemble(pc).observations)
        XCTAssertEqual(Set(tr.keys), [1, 2])
        XCTAssertTrue(tr[1]!.allSatisfy { $0.side == .near }); XCTAssertTrue(tr[2]!.allSatisfy { $0.side == .far })
        let near = gt(pc)["near"]!
        XCTAssertLessThan(tr[1]!.map { simd_length($0.footWorld! - near[$0.frame]) }.max()!, 0.4)
    }

    func testMissingPlayerIsNotReplacedByLineJudge() throws {
        let pc = try scene("gap_far_player")
        let far = gt(pc)["far"]!
        for o in assemble(pc).observations where o.trackID == 2 {
            XCTAssertLessThan(simd_length(o.footWorld! - far[o.frame]), 0.6, "frame \(o.frame)")
        }
    }

    func testNoCameraKeepsTwoCentralPeople() throws {
        let pc = try scene("no_camera")
        let tr = byTrack(assemble(pc).observations)
        XCTAssertEqual(Set(tr.keys), [1, 2])
        let nearPx = Fx.v2(pc.raw["near_px"])
        let du = tr[1]!.map { abs(($0.bbox.x1 + $0.bbox.x2) / 2 - nearPx[$0.frame].x) }
        XCTAssertLessThan(NP.median(du), 10)
        XCTAssertTrue(tr[1]!.allSatisfy { $0.footWorld == nil && $0.side == .near })
        XCTAssertTrue(tr[2]!.allSatisfy { $0.side == .far })
    }

    func testDoublesPartnersCrossingKeepIdentity() throws {
        let pc = try scene("doubles_crossing")
        checkIdentity(assemble(pc, doubles: true).observations, gt(pc), ["n_b": 1, "n_a": 3, "f_d": 2, "f_c": 4], tol: 0.45)
    }

    /// Partners swap sides while hidden for 1 s: colours decide. The frames are rendered
    /// here and the descriptors computed by the Swift port (not injected).
    func testDoublesSideSwitchResolvedByAppearance() throws {
        let pc = try scene("doubles_side_switch")
        let rects = Fx.list(pc.raw["rects"]).map(Fx.rows)
        let W = pc.meta.width, H = pc.meta.height
        var frames: [PlayerCandidates] = []
        var bitExact = 0, total = 0
        for (i, (f, d)) in zip(pc.frames, pc.detections).enumerated() {
            var img = ImageU8(width: W, height: H, channels: 3, repeating: 90)
            for r in rects[i] {                                             // cv2.rectangle, filled, inclusive
                let x1 = max(0, Int(min(r[0], r[2]))), x2 = min(W - 1, Int(max(r[0], r[2])))
                let y1 = max(0, Int(min(r[1], r[3]))), y2 = min(H - 1, Int(max(r[1], r[3])))
                if x1 > x2 || y1 > y2 { continue }
                for y in y1...y2 { for x in x1...x2 {
                    img[x, y, 0] = UInt8(r[6]); img[x, y, 1] = UInt8(r[5]); img[x, y, 2] = UInt8(r[4])
                } }
            }
            let c = Candidates.build(frame: f, detections: d, camera: pc.camera, imageSize: pc.meta.size, image: img)
            if let py = pc.appearance[i], let sw = c.app {
                total += 1
                if py.map(\.bitPattern) == sw.map(\.bitPattern) { bitExact += 1 }
            }
            frames.append(c)
        }
        XCTAssertEqual(bitExact, total, "Swift descriptors of the rendered frames == Python's")
        let tr = byTrack(PlayerTracker.assembleTracks(frames, meta: pc.meta, camera: pc.camera, doubles: true).observations)
        XCTAssertTrue(Set(tr.keys).isSuperset(of: [1, 3]))
        let g = gt(pc)
        for (tid, name) in [(1, "b"), (3, "a")] {                           // b starts at y < 0 → id 1
            let o = tr[tid]!
            XCTAssertLessThan(o.map { simd_length($0.footWorld! - g[name]![$0.frame]) }.max()!, 0.3, "\(tid) \(name)")
            XCTAssertLessThanOrEqual(o.map(\.frame).min()!, 2)
            XCTAssertGreaterThanOrEqual(o.map(\.frame).max()!, pc.meta.nFrames - 3)
        }
        // without images the same scene has no evidence for the swap
        let plain = zip(pc.frames, pc.detections).map {
            Candidates.build(frame: $0.0, detections: $0.1, camera: pc.camera, imageSize: pc.meta.size)
        }
        let tr0 = byTrack(PlayerTracker.assembleTracks(plain, meta: pc.meta, camera: pc.camera, doubles: true).observations)
        let late = tr0[1]!.filter { $0.frame >= 100 }.map { $0.footWorld!.y }
        XCTAssertLessThan(NP.median(late), 0)                                  // stays on its own side
    }

    // MARK: pose / appearance / smoothing / stats

    func testSittingScoreStandingSeatedLunge() throws {
        let s = Fx.dict(Fx.dict(try Fx.load("misc"))["sitting"])
        let out = PlayerGeometry.sittingScore(kps: KeypointArray(values: Fx.rows(s["kps"]).flatMap { $0 }))
        XCTAssertEqual(out[0], 0); XCTAssertGreaterThan(out[1], 0.9); XCTAssertEqual(out[2], 0)
    }

    func testAppearanceDescriptorSeparatesColours() throws {
        let pc = try scene("net_lunge_side")
        let d = pc.detections[0]
        let kps = KeypointArray([d.keypoints[0]])
        var desc: [[Float]] = []
        for bgr in [(30, 30, 220), (32, 34, 215), (220, 120, 20)] {
            var img = ImageU8(width: 1280, height: 720, channels: 3, repeating: 90)
            let xs = [5, 6, 11, 12].map { kps.x(0, $0) }
            let x1 = Int(xs.min()!) - 6, x2 = Int(xs.max()!) + 6, y1 = Int(kps.y(0, 5)), y2 = Int(kps.y(0, 11))
            for y in min(y1, y2)...max(y1, y2) { for x in x1...x2 {
                img[x, y, 0] = UInt8(bgr.2); img[x, y, 1] = UInt8(bgr.1); img[x, y, 2] = UInt8(bgr.0)
            } }
            desc.append(AppearanceDescriptor.descriptors(img, boxes: [d.boxes[0]], kps: kps))
        }
        XCTAssertLessThan(AppearanceDescriptor.distance(desc[0][...], desc[1][...]), 0.1)
        XCTAssertGreaterThan(AppearanceDescriptor.distance(desc[0][...], desc[2][...]), 0.4)
        XCTAssertEqual(AppearanceDescriptor.distance(desc[0][...], nil), 0)
    }

    func testRTSSmootherReducesNoiseAndFillsGaps() throws {
        let m = Fx.dict(Fx.dict(try Fx.load("misc"))["rts"])
        let t = Fx.nums(m["t"]), z = Fx.v2(m["z"])
        let truth = t.map { SIMD2(1.5 * sin(2 * $0), 2.0 * $0 - 1.0) }
        let sm = PlayerViterbi.rtsSmooth(t: t, z: z, r: [Double](repeating: 0.1, count: t.count))
        // the fixture adds a leading gap (frames 0-2) to the Python test's series; score from frame 3
        let ok = z.indices.filter { z[$0].x.isFinite }
        let raw = (ok.map { simd_length_squared(z[$0] - truth[$0]) }.reduce(0, +) / Double(ok.count)).squareRoot()
        let span = 3..<sm.count
        let rms = (span.map { simd_length_squared(sm[$0] - truth[$0]) }.reduce(0, +) / Double(span.count)).squareRoot()
        XCTAssertLessThan(rms, 0.6 * raw)
        for i in 40..<50 { XCTAssertLessThan(simd_length(sm[i] - truth[i]), 0.2) }
    }

    func testMovementStatsKnownPath() {
        let n = 150, fps = 30.0                                     // 5 s at 30 fps, 2 m/s along y
        var obs = (0..<n).map { f in
            PlayerObservation(frame: f, trackID: 1, bbox: BBox(x1: 0, y1: 0, x2: 0, y2: 0), score: 0.9, side: .near,
                              footWorld: SIMD2(-3.0, -2.5 + 2.0 * Double(f) / fps))
        }
        obs += (0..<n).map { f in
            PlayerObservation(frame: f, trackID: 2, bbox: BBox(x1: 0, y1: 0, x2: 0, y2: 0), score: 0.9, side: .far,
                              footWorld: SIMD2(3.0, 0.0))
        }
        let st = Movement.stats(obs, side: .near, timestamps: nil, fps: fps)
        XCTAssertEqual(st.distanceM, 2.0 * Double(n - 1) / fps, accuracy: 0.02 * 2.0 * Double(n - 1) / fps)
        XCTAssertEqual(st.avgSpeedMs, 2.0, accuracy: 0.06)
        XCTAssertEqual(st.maxSpeedMs, 2.0, accuracy: 0.1)
        XCTAssertEqual(st.heatmap.count, Heat.rows); XCTAssertEqual(st.heatmap[0].count, Heat.cols)
        XCTAssertEqual(st.heatmap.flatMap { $0 }.reduce(0, +), 1.0, accuracy: 1e-3)
        let row = Int(3.0 / CourtModel.halfLength * Double(Heat.rows))
        XCTAssertEqual(st.heatmap[row].reduce(0, +), 1.0, accuracy: 1e-3)
        XCTAssertTrue(st.courtCoverage > 0 && st.courtCoverage <= 1)
        let far = Movement.stats(obs, side: .far, timestamps: nil, fps: fps)
        XCTAssertEqual(far.distanceM, 0); XCTAssertEqual(far.courtCoverage, 1.0 / 120, accuracy: 1e-3)
        let empty = Movement.stats([], side: .near, timestamps: nil, fps: nil)
        XCTAssertEqual(empty.distanceM, 0); XCTAssertEqual(empty.heatmap.count, Heat.rows)
    }

    func testMovementStatsUsesListTimestamps() throws {
        let pc = try scene("singles_240")
        let st = Movement.stats(assemble(pc), side: .near)
        XCTAssertTrue(st.trackedS > 0.5 && st.trackedS <= 8.0); XCTAssertGreaterThan(st.distanceM, 0)
        XCTAssertLessThan(st.maxSpeedMs, PlayersConfig.default.speedCap)
    }

    func testFarCropMergeDropsPeopleCutByTheCrop() {
        let kp = [Keypoint](repeating: Keypoint(x: 0, y: 0, conf: 0), count: 17)
        let full = FrameDetections(boxes: [BBox(x1: 400, y1: 120, x2: 440, y2: 220), BBox(x1: 500, y1: 200, x2: 580, y2: 420)],
                                   scores: [0.6, 0.9], keypoints: [kp, kp])
        let crop = FrameDetections(boxes: [BBox(x1: 300, y1: 69, x2: 341, y2: 171), BBox(x1: 398, y1: 150, x2: 481, y2: 250)],
                                   scores: [0.8, 0.7], keypoints: [kp, kp])
        let out = mergeROI(full: full, crop: crop, roi: PixelRect(x1: 100, y1: 50, x2: 900, y2: 300),
                           imageSize: ImageSize(width: 1280, height: 720))
        XCTAssertEqual(out.n, 2)
        XCTAssertEqual(out.scores.sorted(), [0.8, 0.9])
        let near = out.boxes.max { $0.y2 < $1.y2 }!
        XCTAssertEqual(near, BBox(x1: 500, y1: 200, x2: 580, y2: 420))
    }
}
